                           r"|/dev/(tcp|udp)/\S+[^;\n]{0,50}\s0[<>]&[12]\b|\bexec\s+\d+<>\s*/dev/(tcp|udp)/"
                           r"|\bsocat\b[^;|&\n]{0,300}\b(exec|system):[^\s]{0,40}\b(ba|z|da|k)?sh\b"
